BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (264::BIGINT, 'Muy buen profe, explica de manera correcta y sus trabajos no son demasiado difíciles. Muy buena gente si usted le habla, eso sí, no le interrumpa la clase o le haga preguntas tontas por que se le nota chistoso. Buen profe que si le dedica a la materia, solo asegurarse de hacer los trabajos bien'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'e694e78d143c549c6c175df50cd85d652323871b3b10c9a46c300d4357822623'::TEXT, ARRAY[1249]::BIGINT[]),
    (264::BIGINT, 'Diego es un muy buen profe, explica todo muy bien y resuelve cualquier duda, los proyectos son bastante grandes, pero el tiempo que da para hacerlos es adecuado, si se hacen las cosas con tiempo 0 problema'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'a60d9e7d0fb10619c7d0bd8a9f38c000d1c0f4742b8a9a5a9aeeea4822286789'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Muy buen profesor, la mitad del curso son trabajos de los que enseña en clase y la otra mitad es un proyecto de todo lo que se vió en el curso, que con buen tiempo, se sacó fácil. Enseña bastante bien, desde 0 para que todo el mundo entienda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '5ab1a752481eb7277467e1a44c5a1ce82c1181c9a37ccb5a5329afd6bd44d276'::TEXT, ARRAY[1043]::BIGINT[]),
    (264::BIGINT, 'El señor diego mora, para mi el mejor profe de compu. Sabe un monton y es super buena nota. Si bien los proyectos son muuy largos, se aprende un monton y no es nada que el no haya enseñado antes. Mejor profe para intro/taller si de verdad quiere aprender. tqm diego'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-11-26T00:00:00+00:00'::TIMESTAMPTZ, '5e6a340bfcc53d192f7fb0d9ef8815995229a181ba0ebd522873c70e766f884f'::TEXT, ARRAY[1020, 1022, 1030]::BIGINT[]),
    (264::BIGINT, 'Es un muy buen profe, sus clases son muy entretenidas y le apasiona enseñar, lo único malo es que los proyectos son muy largos'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, '49ab077e1789fee2533fe5a398ef9da259d14d9396fc24380a4ac5dad93f8944'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'El mejor profe, hace el curso bastante sencillo y el que tenga experiencia dirigiendo proyectos ayuda bastante para el curso. Califica de manera justa las evaluaciones y es flexible con las fechas de entrega del proyecto. Hace quices sorpresa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2025-08-04T00:00:00+00:00'::TIMESTAMPTZ, '2ee003e79a9d34a15ad3927efb3a7bfcff2c59141405d9de8b9a391f37bc480d'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'Es un profe muy chill y muy interesante de oir. Las calificaciones son bastante claras y sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'ff0939a84667e7425af0a7622846bae65ced6c8b6029f25a2b2e0639435aa72d'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'El profe explica excelente, le apasiona enseñar y si se tiene alguna duda el la resulve de varias fromas para que quede 100% claro, algunos proyectos si son más largos que los de los demás profes pero no es nada que el no haya enseñado antes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '5b64c3b2685d94205bb62629a0f1f226b6ab11dde203b525b4cf76c46a37f47a'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor .Clarísimo al enseñar y si tiene alguna duda él se lo explica con paciencia hasta que le quede claro . Flexible con las entregas de los trabajos , pero deja trabajos bastante exigentes de tiempo. Va a salir sabiendo mucho pero prepárese para trabajar bastante en sus proyectos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-05-12T00:00:00+00:00'::TIMESTAMPTZ, '98cba96a2ac8de685b4c04b0e1bf16e64e06e4baa58d42b00704a96636ae2b68'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Buen profesor, pudo abarcar bastantes temas a pesar del tiempo, y nos enseñó el stack MEAN. Este curso es perfecto para una persona que tiene conocimientos básicos web. Flexible con las entregas de los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '6ee0686a97e27685e3cd09cf266c138542e58d3d3c8e5311606472238a8d0e42'::TEXT, ARRAY[1128]::BIGINT[]),
    (264::BIGINT, 'Es buen profe y explica bien, pero no es muy organizado, siempre va atrasado en todo y deja todas las evaluaciones en las ultimas 6 semanas de clase, se sale hasta el día de actas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'b1ce2c222ecc75e25aa0ea54339ab6a802ae671b819c91fe929c5a57b7f8bbce'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Como profesores y persona, Diego es excelente. Con él van a entender todo e incluso enseña poco más de lo que debería, pero complementa bien. La cosa es que tengan buena pareja porque para proyectos sobre todo para POO pone que hagan juegos y si se hace bastante largo. Además terminan en semana 19'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2024-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'dc712a9efc4c5a1a82eae252f78fc0c93a11b7a1e2779516094eee4726d52896'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'En mi opinión, si usted la lleva al suave y quiere aprender bien, Diego Mora es la mejor opción para POO. Enseña los contenidos de manera excelente y da buenos consejos para el ámbito laboral. Sin embargo para POO cuesta mucho pasar, los proyectos son díficiles y sin una buena pareja se va a quedar.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2024-12-10T00:00:00+00:00'::TIMESTAMPTZ, '122090c8a9f81a4dc31233f00e771a77f43b40760449fd46c492a9dc5a640e52'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Buen profesor, explica excelente en los dos cursos, eso si, deja proyectos largos en pareja, si no se encuentra una buena pareja en cualquiera de los cursos seguramente lo pierda, no le recomiendo llevar los dos por que deja las asignaciones para las mismas fechas y preparese para salir en semana 19'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'cfeaea2e0ae81a6e149a7e9c3a27d6a4025757b37709e2f375faf081a1528ee5'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'Explica muy bien la materia, las clases se pasan bien. Pero deja trabajos largo casi a finales de semestre'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c9268016ce0dde41bc278c64e6918fc94cca3348a0052cec44ca399715ed40cb'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'Es buena persona pero sus clases son demasiado desordenadas, y no siempre se ve toda la materia. Muchas veces no da las clases, y los proyectos son complicados de seguir por el desorden. No recomendado para gente que no sabe ya de progra/python, si no saben mejor busquen a otro profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'd9aeb0cf16a9e124fb215a88cf07bab9ce29f83096862880a9c4fee18121e4ee'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'El profe enseña muy bien los contenidos, sin embargo es muy desordenado con las fechas de entregas. Usualmente deja el mayor peso del curso en las últimas semanas donde todo se acumula.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2024-04-03T00:00:00+00:00'::TIMESTAMPTZ, '73180780cb67b4b36f7e6b2c8a59e21b166bc49a71da920a647e673c1caa8f07'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Debo de decir que al principio lo odie. Creo que si tú eres alguien que está empezando con la programación sería bueno intentar con otro profesor que vaya más despacio, de más práctica y así (para llevar intro y taller). De igual manera el profe como persona es un 1000/10. Y en POO 9/10'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'c49bf29cbae000f742edc7a15cb716ff65bc3ba7d4b2c8cc48527587d7adf1bb'::TEXT, ARRAY[1020, 1022, 1030]::BIGINT[]),
    (264::BIGINT, 'Muy pura vida, revisa los trabajos tarde pero no es muy estricto y se nota que le importa más que uno se vaya con el aprendizaje de buenas prácticas de programación y consejos laborales, para ser un curso de 2ndo semestre la dificultad está perfecta. Eso si, hace quices cuando le da la gana.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '32a2ae6687b62823181adcb6f8f030aea5a83fd07feab9fa0e511cfb2033015d'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'Muy buen profe, la verdad es que hace las clases entretenidas y se aprende bastante. Lo recomiendo al 100'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1c2617f3f355ec3f43245bf594293a21e58145787028be478465733fc516d316'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'Este profe fue una bendición de Tatica Dios. Gracias a él pasé modelados, un curso nuevo que otros profes les costó adaptarse. Nos enseñó cosas super importantes no solo en la programación, sino del mundo real en los trabajos que involucra nuestra carrera. Ojalá lo traigan para más cursos de CE'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '6c86b9a547e38dadeb4ee1b6c2d9b0690a592476a061151ea2fb3da69ca1bd6f'::TEXT, ARRAY[2963]::BIGINT[]),
    (264::BIGINT, 'El profe explica bien pero las clases pueden llegar a ser aburridas. Es muy desordenado con los trabajos, dejando demasiado porcentaje de evaluaciones para el final, si matricula con el sepa que las últimas semanas del semestre no va a tener vida, además las instrucciones son poco claras.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9518be0a9b6427db162d7b851959ab35bad4e204c7820db7c97a273efdfc182c'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'En general es un profesor increíblemente bueno, explica super bien, y se nota que le gusta lo que hace. En mi caso ED, me encantó las progras. Para POO no fue el caso, personalmente los juegos son mi debilidad, entonces me costo. Pero en general una excelente opción.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f00b922ef087c1a8c2b1abcb56d1ddda0ef54afc879c1cae04fe54c67e907a80'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'San Diego Mora, el mejor profe que pueden encontrar en el TEC en computacion, el unico dilema es que si apenas vienen iniciando a programar mejor elegir a otro profe, pero si ustedes son muy fresas en la progra metan con este galan que les va a hacer su vida muy feliz'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2023-10-12T00:00:00+00:00'::TIMESTAMPTZ, 'ccb7f48b9ed1794acdf64ed1c10138b66f161bac07e4a4aad90da38b88fb185d'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'El profe es super tuanis. Las progras suelen ser las mismas todos los años, logrables pero empieze con buen tiempo. Se nota que le gusta la progra porque explica super bien y aclara todo lo que sea necesario. A veces hace quiz sorpresa, pero siempre son faciles y da ayuda. Super recomendado!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-05T00:00:00+00:00'::TIMESTAMPTZ, '8392eb146e9a7fc595593d58d22d1a863fe46b649c9454de79e52be2fa3df090'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'El profe siempre es conciso en sus explicaciones y en lecciones y consulta trata de ayudar a sus estudiantes. Prepárese para quices sorpresa y escritos y proyectos complicados, pero posibles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '89aaf0f15fa15292fc030deda649d38ad041fb2e578f3f53a13d12fdff1767cc'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Buen profe, buenas explicaciones que van conforme los proyectos, eso sí se acostumbra a dejar las cosas para lo último'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e4469628096c3ce9b984ad23db4510c7ce0128f7ba3a8120ed6cbd3e961a93cf'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'El profe es una teja. Ademas, es muy claro a la hora de explicar y las clases son cortas. Todo es en grupos casi. Lo unico es que deja las ultimas 2 progras casi que en semana 16 y se entregan un dia antes de actas. Se aprende mucho con el profe en este curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd73bc07ef6e5f2daf754bca67d220837988774b125e255385723524e6356397f'::TEXT, ARRAY[1047]::BIGINT[]),
    (264::BIGINT, 'Diego es un profe que explica muy bien, se da a entender y se preocupa de que los estudiantes hayan entendido. Los proyectos y quizzes son muuuuy difíciles, y hay que ponerle bastantes ganas a la vara para poder pasar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases excelentes']::TEXT[], '2022-11-08T00:00:00+00:00'::TIMESTAMPTZ, '356cde7ed965289f79dadde0eb5b5a2e283a9458d7141113f45f4ae45e89b5e9'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (264::BIGINT, 'Tengo un dilema con Diego, me cae bien pero deja trabajos muy rudos. Con él aprendí a programar y me gustó mucho su forma de enseñar. Pero es bastante desordenado en fechas y los quices para mí eran bastante duros.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, '810fd4d9282886103f114c4815e57653d01f791e3874caf92f9d5561ae4b54da'::TEXT, ARRAY[1029, 1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Explica súper bien y siempre enseña cosas súper útiles para la vida, los proyectos son rudos y largos pero super chivas, además que si usted le pide ayuda el siempre está anuente a darla'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-15T00:00:00+00:00'::TIMESTAMPTZ, '4fbf80b23c6d6e04dae95af8725b72cd834e48357dbff90a4c4fa12a30bfcf64'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (264::BIGINT, 'Muy confuso con los proyectos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '20'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b2d49e738497df77bb22db973bbbff99759d66c0a8f9697a57369d1d96c44108'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Es muy buen profe y explica súper bien, pero es muy desordenado y casi siempre se atrasa con el calendario así que usted termina haciendo proyectos atrasado. Es bueno, pero más que todo para niveles superiores, si usted es primer ingreso, de consejo le daría que busque a otro profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ce8c733ca1d7528718af198cef599d996a257ca00f1608cf0bb8cd72a4a8e49c'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'El profe es muy pura vida siempre y cuando uno demuestre interés en la clase. Él sabe mucho y ayuda bastante. Las progras son bastante largas y pesadas, pero realizables. También es flexible con el tiempo de entrega. Se aprende bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '3656a438d96d98f54c68929c6641ad7df3ed40677334f8174036dfeb6a2afc78'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'El profe explica excelente, es el mejor en eso. Sin embargo, es demasiado desordenado con las evaluaciones y al final toca correr tanto que uno no sale bien con los proyectos. Si lleva varios cursos, no matricule con él porque pierde el curso, si quiere aprender mucho, hágalo.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '40'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'dfbcdd99bcb5dd9ebe2940051fdeee37ae1b8e437328936b967007a59648f4ee'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Se aprende muchísimo en el curso. Las progras son larguísimas, y las fechas desordenadas, necesita demasiado tiempo para sacarlas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6bd6ff9cde3f60212cc548778fa3a0d068f415bd0ee77aa26cdfe71b3d7a116b'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'No se asuste por las progras, al inicio parecen super complicadas, pero se sacan. Recomiendo que trabaje en grupo, ojalá con alguien que conozca al profe o que también lleve POO con él. Lo malo es que las progras valen 25% cada una y si le va mal en una ya se pone muy difícil el tema.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'eca503023a802f5e626d91c6a7b8a1c83551f4c8dce09b886c25e19a5606ebd9'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Ese papucho es un crack explicando y deja en claro todos los temas del curso, las progras si son un poco largas y complejas pero si tiene mucho tiempo las saca, también es un toque desordenado con las fechas pero si quiere correr este profe es para usted'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '52829b31e2fe2fe1a25ba09c5d30f318b16785806ea6cc26572c54736d1e8cc4'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Es un buen profe y explica muy bien. El problema es que es un desastre. Deja literalmente todo para el final y no hace tareas, labs, o quizes. Dios libre se le va el internet y se pierde la clase, porque al final ya ni se molestaba por subir las clases.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '04d138c737373ec957c95113dceceda8052dd388f2bc6e1ab2bf9d7f486ba77d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'La verdad es de los mejores profes de compu, siempre que pueda trate de llevar con él. Explica super bien y los trabajos no son tan pesados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'fb218a231e539617d63effed2f6257ef8450ac28f838a60fec4750a4c157a063'::TEXT, ARRAY[1128]::BIGINT[]),
    (264::BIGINT, 'Diego es el mejor profe de la escuela, enseña muy bien y lo que enseña es realmente útil para la carrera, cualquier curso que pueda llevar con él llévelo sin dudarlo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'd5a83dffa3099c2ba50a95f3b8ceb39c1b50de40e47e31265cd833a7fc90ae79'::TEXT, ARRAY[1128]::BIGINT[]),
    (264::BIGINT, 'Súper bueno explicando. Con él uno aprende demasiado. Recomendado. Solo que es un poco desordenado con las evaluaciones y fechas. Entonces si no le importa correr a final de semestre lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '056dae55d9917a5697e3422c91daa32b9ceb1dff83a5eb80d69daa22f74cab92'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor, solo que las progras son algo voladas, prepárese para programar mucho! Se aprende demasiado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-04-15T00:00:00+00:00'::TIMESTAMPTZ, 'd381c16f21f96f8dd09b6c729b6b5ed9fc67398e372513dcdad8bd914bdb75b2'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (264::BIGINT, 'Diego es muy buen profe y es muy pura vida. Es un poco desordenado y siempre deja las evaluaciones para fin de semestre. Dejó 2 progras y algunos quices, la segunda valía mucho. El curso lo enfoca en enseñar herramientas útiles y actuales, le interesa que los estudiantes aprendan.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '80480c8b35ed66ebff77d707daf0c1cd32cbba67134aee5a21b1a92bbb007b9d'::TEXT, ARRAY[1043]::BIGINT[]),
    (264::BIGINT, 'Las clases son muy buenas, se aprende bastante y se nota que le gusta enseñar. Las progras son rudas, este semestre dejó 2 y la segunda era gigante. Deja todo para final de semestre.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'cb521b3aca9f28b208184af928d8a1ca0605525427dcfe392585508ef64f6b1f'::TEXT, ARRAY[1043]::BIGINT[]),
    (264::BIGINT, 'Es un excelente profesor, explica muy muy bien y se nota que sabe de lo que habla. Da ejemplos que son muy útiles para las progras, y las explicaciones de los patrones de diseno fueron muy útiles también para ellas. Además es muy buena nota, y ayuda con cualquier duda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ffaa581658a5a6b3787e5649898d73f2b2094aee7b45008cabf0e0c61aee386e'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Diego es muy buen profe explicando, no creo que encuentre un profe mejor en ese sentido. Las primeras semanas no se hace nada, y deja todo en las ultimas semanas por lo que se hace demasiado pesado... no recomiendo llevar POO y ED a la vez...'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'eeb868a6f3a10de0d72d9bf6bc10265681d17cd993981a77be95a888e0dfe8b1'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (264::BIGINT, 'Considero que es un buen profe. Sin embargo, hace explicaciones demasiado largas y es muy difícil que los estudiantes se mantengan concentrados durante toda la clase. Las primeras 7-8 semanas no se hace nada, pero luego deja proyectos demasiado grandes y con poco tiempo para hacerlos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-12-28T00:00:00+00:00'::TIMESTAMPTZ, '56ea98c1da5aa778e8ff7b7ba7f9e0d3e086983f736489878d9375812e6d3cb0'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Excelente profe, explica toda a materia muy bien. Las progras son un poco largas pero no son complicadas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-04T00:00:00+00:00'::TIMESTAMPTZ, 'd9fd2d0f8520a0ed8fece9bf409185bc691e6a2442bf41e1886ebc62b421a7bb'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Dieguito Mora es lo mejor en la carrera, tan excelente e inspirador'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'e1321111829894a08134c994ecf9923882068def8fd92b3ff8f4b49e14d1ef8a'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Explica muy bien , atiende las dudas, deja todo muy claro además se ve que es apasionado a la carrera, y te contagia ese entusiasmo. No dejó examenes, pero las progras que deja son un poco difíciles, pero si tiene dudas las responde muy bien, recomiendo empezarlas el día 0.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '45'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '7c12a51700371233757b0d46ed979d6ac812e02760e50da7f65d592e1b54dc50'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Para mi de los profes que están actualmente es el mejor, en diseño no deja exámenes, son solo proyectos, tareas cortas y quices. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '60828d22c0fd6c94d61d53eb48d84b17ff263ca5b5adbb5faf8fdbd93d67640c'::TEXT, ARRAY[1047]::BIGINT[]),
    (264::BIGINT, 'Es excelente profesor, muy claro en sus explicaciones y conoce bien los temas del curso. Las progras son pesaditas, se lleva su rato, así que considere eso al matricular con él pero lo compensa el hecho de que explica muy bien y se aprende mucho. Muy bueno aclarando dudas también. Súper recomendado!'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '0bae9440a63ca2a0ebf00d1e2dc8db5593b1230d829dd3044d900d1e6c846057'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'No puede pedir mejor profesor :3 Las progras que deja algunas son largas, pero, él explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'df13b2ea45a399b4928d14b24b0caf17c2b844fabd0c323388c63fedd44088b0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor, sus clases son muuuy claras. Incluso deja salir antes pero no da la sensacion de que haga falta mas tiempo de clase para entenderle. Proyectos GRANDES y DIFICILES pero vale la pena porque se aprende. Muy recomendado pero demanda mucho tiempo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '23f1c167ee76471e73063d498ff05b37f348571881583a3ecd12ea29fcae9ed6'::TEXT, ARRAY[1029, 1030]::BIGINT[]),
    (264::BIGINT, 'El tamaño de los proyectos se compensa con lo bien que explica este profesor. Muy recomendado. Se aprende muchísimo. Las clases virtuales las hace muy entretenidas, cortas pero muuuy claras, igual que la presenciales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '4ac720a87c5ad73d44101708ef26eeb0a0087a28613eecfd89754a0bf98b512c'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Top 10 besto teachers in TEC. Uff, no tengo nada que criticarle a este profe, una teja en todo sentido, da gusto. Espero poder llevar más cursos con él, explica bien, trabajos difíciles pero muy entretenidos, te ayuda demasiado según se lo pidas o lo necesites. Imposible no pasarle!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'd6690e0a9887d6477c4c6a035a906203ddee7a10c3d9e5446f9d6858fc1e473d'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Super bueno para empezar la carrera con la mejor preparacion. Es bastante duro y hace quizes sorpresa pero vale la pena por todo lo que se aprende. Los proyectos fueron muy divertidos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '2cea95a94a7da36bf611e1bf06305ceb1a9a211c5551b72eb7e0f78f57d27822'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Deja proyectos GRANDES, de semana 1 a semana 9 no se hace nada y luego empieza a dejar proyectos seguidos. Deja un proyecto con 22 días de tiempo, pero a la semana siguiente deja otro entonces :/ ! Un aspecto bueno es que no califica duró'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '25'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '2aa5d8482402971c6e0800eb308a6d149c9184b90e593844468b0596930c7900'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Muy buen profesor, en la mayoría de casos entenderá a la primera, enfatiza en explicar con dibujos si hace falta, y si aún así no entiende, vuelve a explicar. Las progras(proyectos) si son algo difíciles, dedíque tiempo y todo bien, se logran. Los exámenes de intro son fáciles, buen profe Chayanne.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '880dc5bf682e49dbe754ffccb809ebda47c0fbf494254ba1f06692404d73505a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'El mejor profe, pero muuuy duro'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '70f96e009da350d61eb9b741c660ff2218dd951a5cbce95e61edd9b1c13fde55'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'El profe explica muy bien la verdad. Si usted tiene dudas él se detiene a explicar hasta que entienda. Las progras requieren dedicarle bastante tiempo, pero, en general Chayanne es buen profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-09T00:00:00+00:00'::TIMESTAMPTZ, '46977d8dad772cf3067c1bb61248684ca7be41da2d72a64d693f38fe3eeea604'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Es demasiado bueno , pero el curso no es fácil , a las progras hay que dedicarle bastante tiempo , si logra hacer los trabajos aprende mucho. Es la mejor opción para llevar este curso .'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'f6dffd07766095c53896a727da6c173ad1796d6a2168ee729840afae5b873f46'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Chayanne es el mejor profesor para este curso, es brillante y sabe transmitir sus conocimientos. El curso es bastante pesado porque deja bastantes mini progras combinadas con progras, pero eso diluye la nota. Las progras de las más voladas que pueden existir pero se pueden hacer.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2019-12-26T00:00:00+00:00'::TIMESTAMPTZ, 'a1adcbb0ee86024a37915d3eddf25b168cbaf5a0deebc61b775f9b955c9bf89c'::TEXT, ARRAY[1047]::BIGINT[]),
    (264::BIGINT, 'Uno pasa sin hacer nada todo el semestre y al final básicamente muere las últimas dos semanas antes de actas. Califica todo: prácticamente un 70% del curso en las últimas semanas con proyectos y exámenes. Explica muy bien y todo, pero las progras son bastante voladas para lo que se ve en clase.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8c14d902264cfe20152d3a5c7c9bbfef71e1a7e0e6e9bf5c6da4c5452ad6a908'::TEXT, ARRAY[1043]::BIGINT[]),
    (264::BIGINT, 'Explica poco , y se vuela con progras difíciles , sin importarle si los estudiantes estan preparados para realizar un proyecto de tal envergadura . Es un profesor que esta lleno de egos . Si desea aprender a programar de verdad hay otras opciones mejores . #profesorpatito'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'b32a255ec680724b0e97106a10458970681fe0e780beda46dc2422aa4550ba52'::TEXT, ARRAY[1022]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor, facilmente de los mejores que tiene la escuela, clases demasiado utiles y se aprende montones, proyectos interesantes y va a lo que importa del curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '587a18cd70c35489a2d225c56ca89b27753d23ffa5a420610b92f1f310e81f69'::TEXT, ARRAY[1047]::BIGINT[]),
    (264::BIGINT, 'Muy buen profesor, las clases son muy buenas y se aprende mucho en el curso, lo único es que los exámenes son rudos aunque no imposibles, empieza desde 0 para que todos entiendan. Siempre llega tarde y va atrasado con las fechas.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '547a758643920e8bae2a0b837d997b491a8f6980ff779d67de20b0d80eba5817'::TEXT, ARRAY[1020]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor, explica bastante claro, los exámenes son rudos y las progras largas pero se aprende un montón al hacerlas. Suele llegar tarde y la clase termina temprano pero no es problema ya que suele distribuir muy bien el desarrollo de la lección.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5326faf32743ed684005e46c9a6d4cf7469381c21115ac887a79c751b463753c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Super buen profe pero demasiado rudo tanto con los examenes como las progras. Deja todo al final, y siempre llega tarde'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '06278c21c297e73e9ba416dd76d54f85335ef071ec039cf75a2445671a8da3e9'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Diego es Diego. Es de los mejores profesores de la escuela y el curso lo deja demasiado claro. Tambien suele requerir menos de las dos horas de clases para las lecciones, lo que ayuda que las clases no sean cansadas. Hay solo una progra al final pero es demasiado larga.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4d564dc3d755f55dbdece38a97158f71b5b0a509faf2aeb2051b6287e95e3eaa'::TEXT, ARRAY[1047]::BIGINT[]),
    (264::BIGINT, 'Explicaciones muy claras, es impuntual, muy irritable y si esto pasa basurea a los estudiantes si le preguntan mucho. En general es bastante bueno, sus progras son muy voladas y requieren bastante tiempo, sus exámenes son muy difíciles , califica regular'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '11a570755f4bdfebb3cf687f39d22f1243580b43e7923a8c7a8da9fc9e849323'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Excelente dando las clases, muy pura vida, llega tarde, largas progras pero que lo obligan a uno a investigar. Es muy bueno en general.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-05-16T00:00:00+00:00'::TIMESTAMPTZ, 'a4fdcdc7065bd78abb872f5db586f960e1970645d0dbd8ad451584f3a483f6f7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Es un Dios en el curso. Explica Increible, los quices uno saca 100 con solo oirlo hablar en clases y sin estudiar, porque explica demasiado bien. No quita nada de tiempo. Si puede meterlo con el, ni lo piense.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ff11be30a66bf5cfd866d4a5fc4f636864f819f02a2feafe0e3f1789e8130d1f'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'Explica manera de forma clara y directa. Un poco de teoría y luego la aplica en un pequeño caso practico. El mismo dice que el examen no le importa tanto como los proyectos. El proyecto rudo pero super tuanis para aprender. Llega tarde. Un buen profe y un chavalazo como persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ebff3c044e4a4fdfaa8bba26fa90dde9e738c6bc5982b1628cd512084e80c32f'::TEXT, ARRAY[1043]::BIGINT[]),
    (264::BIGINT, 'Es super buen profe, las clases no son aburridas. Va mucho al grano. Llega tarde. Ayuda bastante. Las progras y exámenes son bastante difíciles y toman mucho tiempo pero son entretenidas. Es muy gente. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '267d04e5710ddfc8e50cbf3112056e5b3531ada68a25a2539b9affe9d1255ba7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'En las 16 semanas de clase no se hace nada, tal vez como 2/3 quices y 1 tarea; luego 1 examen y 1 proyecto, y se acabó. Sin embargo, en sus clases se aprende bastante, y a pesar de ser un curso teórico no es para nada aburrido, al poner ejemplos de la vida real.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2142686e4add1d697aa16c4a5b3d199c9dd505bb1feeac827e2cf65e1a6c8cef'::TEXT, ARRAY[2494, 2495]::BIGINT[]),
    (264::BIGINT, 'Simplemente es un Dios! Está hecho para impartir este curso sin lugar a duda. A pesar de no ser tan teórico como otros profesores, deja el curso muy a la práctica, enseñando lo necesario para un trabajo real. Cuenta mucho sobre sus experiencias haciendo notar que sabe mucho de administración.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-17T00:00:00+00:00'::TIMESTAMPTZ, '9e5b9d97f331e2f28210c80f51da5e5167128619186081caaccc666e111125d6'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'Explica muy bien la materia, sabe mucho de BD pero es algo irresponsable con entregas y suele llegar tarde, al final el proyecto vale la mitad de la nota y las especificaciones que deja son confusas y poco claras aparte que todo se acumula para el final, aun así en general, es muy buen profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-17T00:00:00+00:00'::TIMESTAMPTZ, '4e771f8790c4d3c040934e73227b493f160caf8eb1b2a762851db1f46ec9b6b1'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Explica muy bien, es de los mejores profesores de computación en este aspecto. Sin embargo, es un profesor muy irreponsable, vago y desorganizado, deja todo para el final.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '342bf901f78e54d22e3a1c7a6b587168948549d0ef9372667ab7678c83df7eb3'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Explica excelente y va al grano siempre, no le importa tanto la teoría sino la práctica. Sin embargo las progras son DEMASIADO largas y requieren mucho tiempo. No recomendado si se lleva bloque completo. Muy impuntual. El curso se pasa si se le dedica el tiempo necesario. Recomendado si se organizan'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '30'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'cd2e042657a0e9284ade65247c2a7b3b2f82629a6c7e713bfac15c54ca145e73'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Excelente... Algo impuntual e irresponsable con las evaluaciones, ya que entrega las notas hasta el puro final, sin embargo, se aprende mucho y las progras realmente concuerdan con lo visto en clase y ayudan mucho. Para estructuras de datos es el más duro, pero es el mejor.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '802b14cf07ee2b84e33e1da8ced9eba05bc2f226db1be9cca08636589b61a575'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Es buen profesor y buena nota con la gente. Tiene el problema de que por irresponsable deja todo para el final. Deja para entrega de actas el 50% del curso que debió haber sido evaluado a lo largo del semestre. No lo recomiendo porque es la segunda vez que llevo con él y no termina la materia.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '4c4a9ffa66eb557b3097e308dfb4c709a60d10f810a1016db0a448a581e2d79f'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Explica bien, sin embargo realiza un sólo proyecto la semana de actas. Lo que hace que se torne demasiado pesado el curso en esa parte , y califica demasiado fuerte'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'dcd25e2c43767e603637530175ab046a91f9ae6fc2c676d7487413b70313eaff'::TEXT, ARRAY[1037]::BIGINT[]),
    (264::BIGINT, 'Es muy buena nota y explica bastante bien, pero es algo desordenado. Sus progras son rudas y hay veces que no quedan lo suficientemente claras. Pero en general es un buen curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8475f2e43257fe5d039809c4ad898e547ebdd5c30fef0e2527e0a878c60bb45a'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'El profe es excelente explicando la materia del curso, quices todas las semanas, progras dificiles y es un poco irresponsable es terminos de revisar las evaluaciones, en general es muy buen profe pero si hay que ponerle bastante'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0d3ed99d190e575a31940ec14d1e9824ff9cd9331c997d2480d750b0af8ce788'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Es buena nota. Explica claro y atiende dudas. Pareciera un poco vago porque todo lo deja para el final, tareas y cuices. No hace muchos cuices y los exmanes son accesibles e incluso sencillos. Pueda ser que al final te deje una progra que te va a joder. Muy recomendado!!!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cf65f90801322f5b8a21e9789629fd3dd8961da87584ecb2c9aded1daa7943f8'::TEXT, ARRAY[1253]::BIGINT[]),
    (264::BIGINT, 'Clases magistrales y el profesor sabe la materia muy bien. No exige mucho a lo largo del curso e igual se aprende bastante si se pone atención a lo explicado en clase, lo cual combina con su experiencia lo que lo hace un buen profesor para el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4ed632e9d98a21964bbc6c31a294f4c52e57715154864ee808c07980e21a804d'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'Es un profe muy bueno, aunque siempre llega entre 30min-1h tarde son clases muy buenas y entretenidas. Si le piden tiempo, como grupo, probablemente se los de. Hace progras entretenidas de hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3141c504de05fc1eaa7e4066fdd476ea36dac6cadd002b298174d6faae2afb1d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Perdí este curso con Garro y lo pasé con el. Con Diego es más fácil, el Profe es tuanis, ayuda en lo que uno necesite, pero se aprende más con el otro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '9d779d8b98d1d1ff68979b39f22800284de0c20ddf86bb318f14548eeab2b774'::TEXT, ARRAY[1035]::BIGINT[]),
    (264::BIGINT, 'Muy recomendado. El sabe un montón y conoce la industria. No es obligatorio ir a clases, sin embargo es mejor siempre ir ya que gran parte del curso es trabajo en clases. Algunos trabajos cortos y un trabajo final grande. No se programa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ff43f861a4df7044a6c6a02ea8b018a55ed2003d24f941d03fda3efc44feba9b'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'Es muy buen profe, pero uno no aprende lo que desearía. En algoritmos hay que hacer mucha práctica para aprender. Recomendado para quienes solo quieran pasar el curso. De lo contrario, matricule con Garro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'd674bb10a2a057a530864bbf2ab2968ee85c225c942e1c41a76763fc4bba8edd'::TEXT, ARRAY[1035]::BIGINT[]),
    (264::BIGINT, 'Buen profesor, explica hasta que uno entienda. Las progras y exámenes son un poco difíciles pero se logra. Recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2016-05-26T00:00:00+00:00'::TIMESTAMPTZ, '2d5c8f718360ee79b398587d82ab7397f73241a51806b64b8f41df3a6e9565b3'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'muy buen profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2016-05-06T00:00:00+00:00'::TIMESTAMPTZ, 'b7acb1b4840ac5b237f37f32712735f54b074e9c11295560ba8134328fe603c2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Excelente profe! Super buena gente, explica muy bien y siempre brinda ayuda. Explica y vuelve a explicar todas las veces que usted necesite. No exige más de lo que usted puede dar ni pone muchas tareas. Los proyectos no son fáciles, pero si usted se esfuerza lo logra.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '6b3b61d07f795ec72839e0e7afbd81609f6ff2152c739fb33fa102b031fb1216'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (264::BIGINT, 'Muy buen profesor, siempre aclara todas las dudas que uno tenga. Las clases no son aburridas. Se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '12b4dcf24066688816c2eb339bafce2e83f1355772250a7e1ea3ffebd28ff1ba'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Un profe muy pura vida, con el que se logra una buena interacción, si uno tiene una duda, la responde, normalmente saca las dudas. Las progras son difíciles, pero las explicaciones que da en clase complementan la dificultad que tienen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '38d84b09ae2d3e66b27b0a21cf952b884e76b23f2097c6ca35106503c928a75f'::TEXT, ARRAY[1029]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor y persona, hace que las clases sean entretenidas ya que realiza dinámicas siempre que se pueda. Utiliza su experiencia para dar ejemplos y responde cualquier duda con muchísima claridad. Es fácil de pasar y no hay que trabajar tanto como con otros profesores.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, '9f673acff2b1d1bb9c63e3ea690993a076dc558adb7fe6e9d661ee71b205cea6'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'No es tan buen profe. Si puede meter con alguien mas, entonces mejor. Este profe solo habla de plata y plata, entonces aburre. Ademas de que le gusta burlarse de un estudiante e intimidarlo si este no esta de cuardo con lo que el dice o hace... Simple, no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'f97515c212b631e031ec600137102eaa28b0159cee336f4044e96428ad5d1896'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Es muy bueno, sólo que sus progras son muy difíciles, pero es el mejor profes para estos cursos. Muy muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, '905bfe1a43184d04e596ee235a415611775f62860233aa0e2558b3f8ebf20767'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (264::BIGINT, 'Si lo que va a meter es AP, mejor metalo con Jaime, así aprende más y es un curso muy bueno.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'bed7260ddd9a7d82f500918117a0f9a244a3f5e21ed6878a9706b7d01055558c'::TEXT, ARRAY[1052]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor, explica con claridad, es puntual, se preocupa porque sus estudiantes aprendan, los proyectos son interesantes y útiles'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-15T00:00:00+00:00'::TIMESTAMPTZ, '9708b365b3a5eb0a358cb0d59aa9c20fa5a3dce104a7e415ead3afd5818b705b'::TEXT, ARRAY[1043, 1037]::BIGINT[]),
    (264::BIGINT, 'Excelente profe, ayuda y explica bien'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2015-08-02T00:00:00+00:00'::TIMESTAMPTZ, '3eefcafab609fb37c8a2f3ffce7d01757c3495cf929479e978b099320c89a5da'::TEXT, ARRAY[1020]::BIGINT[]),
    (264::BIGINT, 'Muy buen profesor explica muy bien, deja las cosas muy claras, se le nota interés porque la gente aprenda. Algo que no es tan bueno es que cuando lleve POO no vio la materia del plan se aprendió mucho pero del curso muy poco, pero si quiere aprender buenas practicas de programación se le recomiendo. No es alguien de regalar puntos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2015-07-27T00:00:00+00:00'::TIMESTAMPTZ, '8dafca817df2cfcf62580ceb38931e5218dc4980de8ca4c211ebdb06d4ed559f'::TEXT, ARRAY[1020, 1022, 1030]::BIGINT[]),
    (264::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'c7d41946e94f4eece09566c1c0d6759bab0de84895f8e2b48c4ba3d9df99b94c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Enseña bien bastante bien. Deja progras bastante tuanis y no demasiado rudas. Cae muy bien. Para ese curso es el mejor profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'a5aeabe50f78f3d52d202c1add0559fe170e61f2d978af928ad10782e3a7ad8b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (264::BIGINT, 'Si no le gustan las progras pesadas, no se lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'dc35cfb604c3d60c56925f82cc30df6b791149de81f2a4c7952bb1ce91a9b865'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '5a9a0e9a968aeafb63c2590ab95c25dd4a0b3ec5b39ad8b9fe86165975c58aa7'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'd08a0fc63a40b8bd0a44c1dc0a61a1ade70b13424c380915db16ea440816d7c0'::TEXT, ARRAY[1030]::BIGINT[]),
    (264::BIGINT, 'Excelente profesor! Explica muy bien, sus progras son rudas pero gracias a que es excelente explicando se pueden realizar fácilmente. Es comprensivo, muy bueno como persona. Juega de rudo y lo es, pero no tanto como otros. Se aprende de verdad sobre el curso y sobre temas adicionales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0b8f193ab9865e15ab0b799513de3a2965e3db19bc0a3b9f063634be4351f00d'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (264::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2f5772c62b9cfd0e0c70d90ddee8e8e6469ada1e3ebd25658fb06cf50abbc99d'::TEXT, ARRAY[1029]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
